<?php
declare(strict_types=1);namespace App\Http\Controllers\Hrd;use App\Http\Controllers\Controller;use App\Http\Requests\Hrd\StoreCashAdvanceRequest;use App\Models\{Personnel,PersonnelCashAdvance};use App\Services\Hrd\CashAdvanceService;use Illuminate\Http\{RedirectResponse,Request};use Illuminate\View\View;
class PersonnelCashAdvanceController extends Controller{public function index(Request$r):View{$q=PersonnelCashAdvance::with(['personnel','payments'])->latest('request_date');if(!$r->user()->can('personnel-cash-advance.view')){$p=$r->user()->personnel;if(!$p)abort(403);$q->where('personnel_id',$p->id);}return view('hrd.cash-advance.index',['title'=>'Kasbon Pegawai','advances'=>$q->paginate(20),'personnel'=>Personnel::where('is_active',true)->orderBy('full_name')->get()]);}public function store(StoreCashAdvanceRequest$r):RedirectResponse{$v=$r->validated();$p=$r->user()->can('personnel-cash-advance.create')&&isset($v['personnel_id'])?Personnel::findOrFail($v['personnel_id']):$r->user()->personnel;if(!$p)abort(403);$advance=PersonnelCashAdvance::create(['personnel_id'=>$p->id,'cash_advance_number'=>'KB-'.now()->format('YmdHis').'-'.$p->id,'request_date'=>today(),'amount'=>$v['amount'],'remaining_amount'=>$v['amount'],'installment_amount'=>$v['installment_amount'],'installment_type'=>'fixed','reason'=>$v['reason'],'note'=>$v['note']??null,'status'=>'pending','created_by'=>$r->user()->id]);activity('hrd')->causedBy($r->user())->performedOn($advance)->log('Kasbon dibuat.');return back()->with('status','Kasbon berhasil diajukan.');}public function transition(PersonnelCashAdvance$a,string$action,Request$r,CashAdvanceService$s):RedirectResponse{$permissions=['approve'=>'personnel-cash-advance.approve','reject'=>'personnel-cash-advance.approve','disburse'=>'personnel-cash-advance.disburse'];abort_unless($r->user()->can($permissions[$action]??'never'),403);$s->transition($a,$action,$r->user());return back()->with('status','Status kasbon diperbarui.');}public function payment(PersonnelCashAdvance$a,Request$r,CashAdvanceService$s):RedirectResponse{$v=$r->validate(['amount'=>'required|numeric|min:1','method'=>'required|in:manual_cash,manual_transfer']);$s->pay($a,(float)$v['amount'],$v['method'],$r->user());return back()->with('status','Pembayaran kasbon dicatat.');}}
